export function orderStops(depot: Stop, stops: Stop[]): Stop[] {
  const left = [...stops];
  const ordered: Stop[] = [];
  let at = depot;
  while (left.length > 0) {
    left.sort((a, b) => distanceKm(at, a) - distanceKm(at, b));
    at = left.shift()!;
    ordered.push(at);
  }
  return ordered;
}

